/**
 * @method
 * @name backpack#fetchFundingRateHistory
 * @description fetches historical funding rate prices
 * @see https://docs.backpack.exchange/#tag/Markets/operation/get_funding_interval_rates
 * @param {string} symbol unified symbol of the market to fetch the funding rate history for
 * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
 * @param {int} [limit] the maximum amount of funding rate structures
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
 */
func (this *Backpack) FetchFundingRateHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]FundingRateHistory] {
	ch := make(chan AsyncResult[[]FundingRateHistory], 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Backpack) fetchFundingRateHistoryBody(ch chan AsyncResult[[]FundingRateHistory], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchFundingRateHistory() requires a symbol argument"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	if limit != nil {
		request["limit"] = mathMin(limit, 1000) // api maximum 1000
	}

	listEp2338 := <-this.PublicGetApiV1FundingRates(this.Extend(request, params))
	if listEp2338.Err != nil {
		panic(listEp2338.Err)
	}
	var response []any = listEp2338.Value
	//
	//     [
	//         {
	//             "fundingRate": "0.0001",
	//             "intervalEndTimestamp": "2025-07-22T00:00:00",
	//             "symbol": "BTC_USDC_PERP"
	//         }
	//     ]
	//
	var rates []any = []any{}
	var rawRates []any = this.ToArray(response)
	for i := 0; i < len(rawRates); i++ {
		var rate any = DerefScalar(rawRates[i])
		var datetime *string = this.SafeString(rate, "intervalEndTimestamp")
		var timestamp *int64 = this.Parse8601(datetime)
		rates = append(rates, map[string]any{
			"info":        rate,
			"symbol":      market["symbol"],
			"fundingRate": this.SafeNumber(rate, "fundingRate"),
			"timestamp":   timestamp,
			"datetime":    datetime,
		})
	}
	var sorted []any = this.SortBy(rates, "timestamp")

	ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(this.FilterBySymbolSinceLimit(sorted, this.SafeString(market, "symbol"), since, limit))}
	return nil
}

